inline void AppendToJson(std::string& json_str, const Bundle& value) {
  bundle_raw* raw = nullptr;
  int len = 0;
  bundle_encode(value.GetHandle(), &raw, &len);
  if (raw == nullptr) {
    json_str += "null";
    return;
  }

  json_str += "\"" + JsonEscape(std::string(reinterpret_cast<const char*>(raw), len)) + "\"";
  free(raw);
}

template <class T>
void AppendToJson(std::string& json_str, const std::list<T>& value) {
  json_str += "[";
  bool first = true;
  for (const auto& i : value) {
    if (!first) json_str += ",";
    first = false;
    AppendToJson(json_str, i);
  }

  json_str += "]";
}

template <class T>
void AppendToJson(std::string& json_str, const std::vector<T>& value) {
  json_str += "[";
  bool first = true;
  for (const auto& i : value) {
    if (!first) json_str += ",";
    first = false;
    AppendToJson(json_str, i);
  }

  json_str += "]";
}

template <class T>
void AppendToJson(std::string& json_str, const std::set<T>& value) {
  json_str += "[";
  bool first = true;
  for (const auto& i : value) {
    if (!first) json_str += ",";
    first = false;
    AppendToJson(json_str, i);
  }

  json_str += "]";
}

template <class K, class V>
void AppendToJson(std::string& json_str, const std::map<K, V>& value) {
  json_str += kJsonObjOpen;
  bool first = true;
  for (const auto& i : value) {
    if (!first) json_str += ",";
    first = false;
    std::string key_str;
    AppendToJson(key_str, i.first);
    if (key_str.empty() || key_str.front() != '"')
      key_str = "\"" + key_str + "\"";

    json_str += key_str + ":";
    AppendToJson(json_str, i.second);
  }

  json_str += kJsonObjClose;
}

