bool TizenActionSchedule::ServiceBase::CheckPrivileges(rpc_port_h port, int method_id) {
  int ret;
  uid_t uid;
  pid_t pid;
  auto found = privilege_map_.find(method_id);
  if (found == privilege_map_.end())
    return true;

  ret = dl_rpc_port_get_peer_info(port, &pid, &uid);
  if(ret == RPC_PORT_ERROR_NONE && uid < kRegularUidMin) {
    _W("Bypass access control. pid(%d), uid(%u)", pid, uid);
    return true;
  }

  for (const auto& privilege : found->second) {
    bool has = false;

    ret = dl_rpc_port_stub_has_privilege_local(
    parent_->GetRaw(), GetSender().c_str(), privilege.c_str(), &has);
    if (ret != 0 || !has) {
      return false;
    }
  }

  return true;
}

