void TizenActionSchedule::ServiceBase::SetContext(void* context) {
  context_ = context;
}

void* TizenActionSchedule::ServiceBase::GetContext() const {
  return context_;
}

TizenActionSchedule::TizenActionSchedule() {
  _W("TizenActionSchedule ctor");
  int ret = rpc_port_stub_create(&stub_, "TizenActionSchedule");
  if (ret != RPC_PORT_ERROR_NONE) {
    _E("Failed to create stub. error(%d)", ret);
    throw InvalidIOException();
  }
  rpc_port_stub_add_connected_event_cb(stub_, OnConnectedCb, this);
  rpc_port_stub_add_disconnected_event_cb(stub_, OnDisconnectedCb, this);
  rpc_port_stub_add_received_event_cb(stub_, OnReceivedCb, this);

  TizenActionSchedule_context_ = std::make_unique<LocalExecution>("TizenActionSchedule", this);
}

TizenActionSchedule::~TizenActionSchedule() {
  _W("TizenActionSchedule dtor");
  for (auto& service : services_) {
    if(!service->GetInstance().empty())
    service->OnTerminate();

    if (TizenActionSchedule_context_ && service->GetContext())
      TizenActionSchedule_context_->Disconnect(service->GetContext());
  }

  TizenActionSchedule_context_.reset();
  if (stub_ != nullptr)
    rpc_port_stub_destroy(stub_);
}

void TizenActionSchedule::Listen(std::shared_ptr<TizenActionSchedule::ServiceBase::Factory> service_factory) {
  service_factory_ = std::move(service_factory);
  int ret = rpc_port_stub_listen(stub_);
  if (ret != RPC_PORT_ERROR_NONE) {
    _E("Failed to listen stub. error(%d)", ret);
    if (ret == RPC_PORT_ERROR_INVALID_PARAMETER || ret == RPC_PORT_ERROR_IO_ERROR)
      throw InvalidIOException();
  }

  TizenActionSchedule_context_->SetListening(true);
}
void TizenActionSchedule::OnConnectedCb(const char* sender, const char* instance, void* user_data) {
  auto* handle = static_cast<TizenActionSchedule*>(user_data);
  auto service = handle->service_factory_->CreateService(sender, instance);

  service->SetParent(handle);
  rpc_port_h port;
  int ret = rpc_port_stub_get_port(handle->stub_, RPC_PORT_PORT_CALLBACK, instance, &port);
  if (ret != RPC_PORT_ERROR_NONE) {
    _E("Failed to get port. error(%d)", ret);
    return;
  }

  service->SetPort(port);
  service->OnCreate();
  handle->services_.emplace_back(std::move(service));
}

void TizenActionSchedule::OnDisconnectedCb(const char* sender, const char* instance, void* user_data) {
  auto* handle = static_cast<TizenActionSchedule*>(user_data);
  auto iter = handle->services_.begin();
  while (iter != handle->services_.end()) {
    if ((*iter)->GetInstance() == instance) {
      (*iter)->OnTerminate();
      iter = handle->services_.erase(iter);
      break;
    }

    iter++;
  }
}

int TizenActionSchedule::OnReceivedCb(const char* sender, const char* instance, rpc_port_h port, void* user_data) {
  auto* handle = static_cast<TizenActionSchedule*>(user_data);
  std::shared_ptr<ServiceBase> service;
  for (auto& iter : handle->services_) {
    if (iter->GetInstance() == instance) {
      service = iter;
      break;
    }
  }

  if (service.get() == nullptr) {
    _E("Failed to find TizenActionSchedule context. instance(%s)", instance);
    return -1;
  }

  rpc_port_h callback_port;
  int ret = rpc_port_stub_get_port(handle->stub_, RPC_PORT_PORT_CALLBACK, instance, &callback_port);
  if (ret != 0) {
    _E("Failed to get callback port. error(%d)", ret);
    return -1;
  }

  rpc_port_parcel_h parcel;
  ret = rpc_port_parcel_create_from_port(&parcel, port);
  if (ret != 0) {
    _E("Failed to create parcel from port. error(%d)", ret);
    return ret;
  }

  return service->Dispatch(port, callback_port, parcel, service);
}

void TizenActionSchedule::OnLocalConnected(void* context, const std::string& sender, const std::string& instance, bool sync) {
  auto service = service_factory_->CreateService(sender, instance);
  service->SetParent(this);
  service->SetContext(context);
  service->OnCreate();
  services_.emplace_back(std::move(service));
  TizenActionSchedule_context_->Connect(context, sync);
}

void TizenActionSchedule::OnLocalDisconnected(void* context, const std::string& sender, const std::string& instance) {
  auto iter = services_.begin();
  while (iter != services_.end()) {
    if ((*iter)->GetInstance() == instance) {
      (*iter)->OnTerminate();
      iter = services_.erase(iter);
      break;
    }

    iter++;
  }

  TizenActionSchedule_context_->Disconnect(context);
}

void TizenActionSchedule::OnLocalReceived(void* context, rpc_port_parcel_h parcel) {
  std::shared_ptr<ServiceBase> service;
  for (auto& iter : services_) {
    if (iter->GetContext() == context) {
      service = iter;
      break;
    }
  }

  if (service.get() == nullptr) {
    _E("Failed to find TizenActionSchedule context. context(%p)", context);
    return;
  }

  service->Dispatch(nullptr, nullptr, parcel, service);
}

